<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserInvitation\Domain\ValueObject\Holder\UserInvitationStatusAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserInvitationStatusAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserInvitationStatusAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getStatus returns null on a freshly created holder.
     */
    public function testStatusNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserInvitationStatusAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isStatusAssigned());
        $this->assertNull($holder->getStatus());
    }
}
class ImplWithUserInvitationStatusAttributeHolderUnitTest
{
    use UserInvitationStatusAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedStatusRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultStatus();
    }
}
